package com.peerlink.app.bot

/**
 * Committed gate capture bodies -- ciphertext only, decoded at runtime with
 * credentials patched in memory (the room1.py contract: the repo ships
 * protocol, never credentials). Both bodies are already public in the
 * kgs-gate-cipher repo; the app reuses the exact proven wire shapes:
 *
 *  - LOGIN: the body every accepted live run (CLI #26..#47) logged in with;
 *    user_id/auth_code/session_id/hash/rqid/version are patched per identity
 *    before sending.
 *  - CREATE_USER: the account-creation body mint.py replays; user_name (and,
 *    on the retry, device_identifier) are patched fresh per attempt.
 */
object GateCaptures {

    const val LOGIN_BODY_HEX =
        ""

    const val CREATE_USER_BODY_HEX =
        ""

    fun bytes(hex: String): ByteArray {
        val out = ByteArray(hex.length / 2)
        for (i in out.indices) {
            out[i] = ((Character.digit(hex[i * 2], 16) shl 4) or
                Character.digit(hex[i * 2 + 1], 16)).toByte()
        }
        return out
    }

    fun decodeBody(hex: String): LinkedHashMap<String, Any?> =
        GateCodec.decode(bytes(hex)) as? LinkedHashMap<String, Any?>
            ?: linkedMapOf()
}
